function distinctNumbers(nums, k) {
  const count = new Map();
  const ans = [];
  for (let right = 0; right < nums.length; right++) {
    const incoming = nums[right];
    count.set(incoming, (count.get(incoming) || 0) + 1);
    if (right >= k) {
      const outgoing = nums[right - k];
      count.set(outgoing, count.get(outgoing) - 1);
      if (count.get(outgoing) === 0) {
        count.delete(outgoing);
      }
    }
    if (right >= k - 1) {
      ans.push(count.size);
    }
  }
  return ans;
}

