function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const roll = rand();
  const span = roll < 0.4 ? 3 : roll < 0.8 ? (size === 'large' ? 300 : 6) : 100000;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * span));
  const k = 1 + Math.floor(rand() * n);
  return [nums, k];
}
